vec2 uv=fragCoord/iResolution.xy;
 if(mod(float(iFrame),8.0)==0.0||mod(float(iFrame),8.0)==7.0){

    vec3 col=texture(iChannel1,uv).rgb;
    if(dot(col,col)>0.005&&mod(float(iFrame),8.0)==0.0){
    fragColor.rgb=vec3(uv,0.0);
    }

    if(mod(float(iFrame),8.0)==7.0){
    col=texture(iChannel0,uv).rgb;
        fragColor.rgb=col;
        fragColor.b=distance(fragColor.rg,uv);
    }
}else{
float uOffset=exp2(8.0-mod(float(iFrame),8.0)-3.0);
vec4 nearestSeed = vec4(-2.0);
float nearestDist = 999999.9;

for (float y = -1.0; y <= 1.0; y += 1.0) {
  for (float x = -1.0; x <= 1.0; x += 1.0) {
    vec2 sampleUV = uv + (vec2(x, y) * uOffset)/200.0;
if (sampleUV.x < 0.0 || sampleUV.x > 1.0 || sampleUV.y < 0.0 || sampleUV.y > 1.0) { continue; }

vec4 sampleValue = tex(sampleUV);
vec2 sampleSeed = sampleValue.xy;

if (sampleSeed.x >= 0.005 || sampleSeed.y >= 0.005) {
  vec2 diff = sampleSeed - uv;
  float dist = dot(diff, diff);
  if (dist < nearestDist) {
    nearestDist = dist;
    nearestSeed = sampleValue;
  }
}
}
}
fragColor.rgb=nearestSeed.rgb;
}


    fragColor.a=1.0;

}

